1: #!/usr/bin/env node
2: /**
3:  * Release script for pi-mono
4:  *
5:  * Usage:
6:  *   node scripts/release.mjs <major|minor|patch>
7:  *   node scripts/release.mjs <x.y.z>
8:  *
9:  * Steps:
10:  * 1. Check for uncommitted changes
11:  * 2. Verify every public workspace package is registered on npm
12:  * 3. Bump version via npm run version:xxx or set an explicit version
13:  * 4. Update CHANGELOG.md files: [Unreleased] -> [version] - date
14:  * 5. Regenerate release artifacts
15:  * 6. Run checks and tests
16:  * 7. Commit and tag the release
17:  * 8. Add new [Unreleased] section to changelogs
18:  * 9. Commit next-cycle changelog updates
19:  * 10. Push main and the tag to trigger CI publication and verified pi.dev announcement
20:  */
21: 
22: import { execSync, spawnSync } from "node:child_process";
23: import { existsSync, readFileSync, writeFileSync } from "node:fs";
24: import { join } from "node:path";
25: import { findPackageDirectories } from "./package-workspaces.mjs";
26: import { getPublicWorkspacePackages } from "./release-packages.mjs";
27: 
28: const RELEASE_TARGET = process.argv[2];
29: const BUMP_TYPES = new Set(["major", "minor", "patch"]);
30: const SEMVER_RE = /^\d+\.\d+\.\d+$/;
31: 
32: if (!RELEASE_TARGET || (!BUMP_TYPES.has(RELEASE_TARGET) && !SEMVER_RE.test(RELEASE_TARGET))) {
33: 	console.error("Usage: node scripts/release.mjs <major|minor|patch|x.y.z>");
34: 	process.exit(1);
35: }
36: 
37: function run(cmd, options = {}) {
38: 	console.log(`$ ${cmd}`);
39: 	try {
40: 		return execSync(cmd, { encoding: "utf-8", stdio: options.silent ? "pipe" : "inherit", ...options });
41: 	} catch (e) {
42: 		if (!options.ignoreError) {
43: 			console.error(`Command failed: ${cmd}`);
44: 			process.exit(1);
45: 		}
46: 		return null;
47: 	}
48: }
49: 
50: function getVersion() {
51: 	const pkg = JSON.parse(readFileSync("packages/ai/package.json", "utf-8"));
52: 	return pkg.version;
53: }
54: 
55: function assertPackagesAreRegisteredWithNpm() {
56: 	const packageNames = getPublicWorkspacePackages().map((pkg) => pkg.name);
57: 	const unregisteredPackages = [];
58: 
59: 	console.log("Checking npm package registration...");
60: 	for (const packageName of packageNames) {
61: 		const result = spawnSync(process.platform === "win32" ? "npm.cmd" : "npm", ["view", packageName, "version", "--json"], {
62: 			encoding: "utf8",
63: 			stdio: ["ignore", "pipe", "pipe"],
64: 		});
65: 
66: 		if (result.status === 0 && result.stdout.trim()) {
67: 			console.log(`  ${packageName}`);
68: 			continue;
69: 		}
70: 
71: 		const output = [result.stdout, result.stderr, result.error?.message].filter(Boolean).join("\n");
72: 		if (output.includes("E404") || output.includes("404 Not Found")) {
73: 			unregisteredPackages.push(packageName);
74: 			continue;
75: 		}
76: 
77: 		throw new Error(output ? `Failed to query npm registration for ${packageName}\n${output}` : `Failed to query npm registration for ${packageName}`);
78: 	}
79: 
80: 	if (unregisteredPackages.length > 0) {
81: 		throw new Error(`The following public workspace packages are not registered on npm:\n${unregisteredPackages.map((packageName) => `  ${packageName}`).join("\n")}\nRegister them before running a release.`);
82: 	}
83: 
84: 	console.log("  All public workspace packages are registered on npm\n");
85: }
86: 
87: function compareVersions(a, b) {
88: 	const aParts = a.split(".").map(Number);
89: 	const bParts = b.split(".").map(Number);
90: 
91: 	for (let i = 0; i < 3; i++) {
92: 		const diff = (aParts[i] || 0) - (bParts[i] || 0);
93: 		if (diff !== 0) {
94: 			return diff;
95: 		}
96: 	}
97: 
98: 	return 0;
99: }
100: 
101: function shellQuote(value) {
102: 	return `'${value.replace(/'/g, `'\\''`)}'`;
103: }
104: 
105: function removeStaleWorkspaceLockEntries() {
106: 	const workspaceVersions = new Map(
107: 		getPublicWorkspacePackages().map((pkg) => [pkg.name, pkg.version]),
108: 	);
109: 	const lockPath = "package-lock.json";
110: 	const lock = JSON.parse(readFileSync(lockPath, "utf8"));
111: 	let removed = 0;
112: 
113: 	for (const [path, pkg] of Object.entries(lock.packages)) {
114: 		if (!path.startsWith("packages/") || pkg.link === true) {
115: 			continue;
116: 		}
117: 		for (const [name, version] of workspaceVersions) {
118: 			if (path.endsWith(`/node_modules/${name}`) && pkg.version !== version) {
119: 				delete lock.packages[path];
120: 				removed++;
121: 				break;
122: 			}
123: 		}
124: 	}
125: 
126: 	if (removed > 0) {
127: 		writeFileSync(lockPath, `${JSON.stringify(lock, null, "\t")}\n`);
128: 		console.log(`Removed ${removed} stale workspace package lock ${removed === 1 ? "entry" : "entries"}.`);
129: 	}
130: }
131: 
132: function stageChangedFiles() {
133: 	const output = run("git ls-files -m -o -d --exclude-standard", { silent: true });
134: 	const paths = [...new Set((output || "").split("\n").map((line) => line.trim()).filter(Boolean))];
135: 	if (paths.length === 0) {
136: 		return;
137: 	}
138: 
139: 	run(`git add -- ${paths.map(shellQuote).join(" ")}`);
140: }
141: 
142: function bumpOrSetVersion(target) {
143: 	const currentVersion = getVersion();
144: 
145: 	if (BUMP_TYPES.has(target)) {
146: 		console.log(`Bumping version (${target})...`);
147: 		run(`npm run version:${target}`);
148: 	} else {
149: 		if (compareVersions(target, currentVersion) <= 0) {
150: 			console.error(`Error: explicit version ${target} must be greater than current version ${currentVersion}.`);
151: 			process.exit(1);
152: 		}
153: 
154: 		console.log(`Setting explicit version (${target})...`);
155: 		run(`npm version ${target} --workspaces --no-git-tag-version --no-workspaces-update && node scripts/sync-versions.js && npm install --package-lock-only --ignore-scripts`);
156: 	}
157: 
158: 	// npm version can temporarily install the previous workspace versions before
159: 	// sync-versions updates inter-package ranges. Remove those stale lock entries,
160: 	// refresh the lockfile, then hydrate from the final dependency graph.
161: 	removeStaleWorkspaceLockEntries();
162: 	run("npm install --package-lock-only --ignore-scripts");
163: 	run("npm ci --ignore-scripts");
164: 	return getVersion();
165: }
166: 
167: function getChangelogs() {
168: 	return findPackageDirectories()
169: 		.map((directory) => join(directory, "CHANGELOG.md"))
170: 		.filter((path) => existsSync(path));
171: }
172: 
173: function updateChangelogsForRelease(version) {
174: 	const date = new Date().toISOString().split("T")[0];
175: 	const changelogs = getChangelogs();
176: 
177: 	for (const changelog of changelogs) {
178: 		const content = readFileSync(changelog, "utf-8");
179: 
180: 		if (!content.includes("## [Unreleased]")) {
181: 			console.log(`  Skipping ${changelog}: no [Unreleased] section`);
182: 			continue;
183: 		}
184: 
185: 		const updated = content.replace(
186: 			"## [Unreleased]",
187: 			`## [${version}] - ${date}`
188: 		);
189: 		writeFileSync(changelog, updated);
190: 		console.log(`  Updated ${changelog}`);
191: 	}
192: }
193: 
194: function addUnreleasedSection() {
195: 	const changelogs = getChangelogs();
196: 	const unreleasedSection = "## [Unreleased]\n\n";
197: 
198: 	for (const changelog of changelogs) {
199: 		const content = readFileSync(changelog, "utf-8");
200: 
201: 		// Insert after "# Changelog\n\n"
202: 		const updated = content.replace(
203: 			/^(# Changelog\n\n)/,
204: 			`$1${unreleasedSection}`
205: 		);
206: 		writeFileSync(changelog, updated);
207: 		console.log(`  Added [Unreleased] to ${changelog}`);
208: 	}
209: }
210: 
211: // Main flow
212: console.log("\n=== Release Script ===\n");
213: 
214: // 1. Check for uncommitted changes
215: console.log("Checking for uncommitted changes...");
216: const status = run("git status --porcelain", { silent: true });
217: if (status && status.trim()) {
218: 	console.error("Error: Uncommitted changes detected. Commit or stash first.");
219: 	console.error(status);
220: 	process.exit(1);
221: }
222: console.log("  Working directory clean\n");
223: 
224: // 2. Verify npm package registration before modifying the worktree.
225: assertPackagesAreRegisteredWithNpm();
226: 
227: // 3. Bump or set version
228: const version = bumpOrSetVersion(RELEASE_TARGET);
229: console.log(`  New version: ${version}\n`);
230: 
231: // 4. Update changelogs
232: console.log("Updating CHANGELOG.md files...");
233: updateChangelogsForRelease(version);
234: console.log();
235: 
236: // 5. Regenerate release artifacts
237: console.log("Regenerating release artifacts...");
238: run("npm run generate:models");
239: run("npm run check:model-data");
240: run("npm run shrinkwrap:coding-agent");

