1: #!/usr/bin/env node
2: 
3: /**
4:  * Validates lockstep versions for published packages, then synchronizes
5:  * internal dependency versions in all workspace packages, including private ones.
6:  */
7: 
8: import { readFileSync, writeFileSync } from "node:fs";
9: import { join } from "node:path";
10: import { findPackageDirectories } from "./package-workspaces.mjs";
11: 
12: const GENERATED_PACKAGE_SUFFIXES = [join("coding-agent", "install-lock")];
13: 
14: const packageRoot = process.argv[2] ?? "packages";
15: const workspacePackages = findPackageDirectories(packageRoot)
16: 	.filter((directory) => !GENERATED_PACKAGE_SUFFIXES.some((suffix) => directory.endsWith(suffix)))
17: 	.map((directory) => {
18: 		const path = join(directory, "package.json");
19: 		return { data: JSON.parse(readFileSync(path, "utf8")), path };
20: 	});
21: const publishedPackages = workspacePackages.filter((pkg) => pkg.data.private !== true);
22: const versionMap = new Map(workspacePackages.map((pkg) => [pkg.data.name, pkg.data.version]));
23: 
24: console.log("Current versions:");
25: for (const pkg of [...publishedPackages].sort((a, b) => a.data.name.localeCompare(b.data.name))) {
26: 	console.log(`  ${pkg.data.name}: ${pkg.data.version}`);
27: }
28: 
29: const versions = new Set(publishedPackages.map((pkg) => pkg.data.version));
30: if (versions.size > 1) {
31: 	console.error("\nERROR: Not all non-private packages have the same version.");
32: 	console.error("Expected lockstep versioning. Run one of:");
33: 	console.error("  npm run version:patch");
34: 	console.error("  npm run version:minor");
35: 	console.error("  npm run version:major");
36: 	process.exit(1);
37: }
38: 
39: console.log("\nAll non-private packages are at the same version (lockstep).");
40: 
41: let totalUpdates = 0;
42: const updatedPackages = new Set();
43: for (const pkg of workspacePackages) {
44: 	for (const dependencyType of ["dependencies", "devDependencies"]) {
45: 		const dependencies = pkg.data[dependencyType];
46: 		if (!dependencies) {
47: 			continue;
48: 		}
49: 
50: 		for (const [dependencyName, currentSpecifier] of Object.entries(dependencies)) {
51: 			// Registry aliases such as `npm:@earendil-works/pi-ai@0.1.2` are never workspace-linked,
52: 			// so lockstep bumping them would point at a version that is not published yet.
53: 			const version = versionMap.get(dependencyName);
54: 			const newSpecifier = version ? `^${version}` : null;
55: 			if (!newSpecifier || currentSpecifier === newSpecifier) {
56: 				continue;
57: 			}
58: 
59: 			console.log(`\n${pkg.data.name}:`);
60: 			console.log(
61: 				`  ${dependencyName}: ${currentSpecifier} → ${newSpecifier}${dependencyType === "devDependencies" ? " (devDependencies)" : ""}`,
62: 			);
63: 			dependencies[dependencyName] = newSpecifier;
64: 			updatedPackages.add(pkg);
65: 			totalUpdates++;
66: 		}
67: 	}
68: }
69: 
70: for (const pkg of updatedPackages) {
71: 	writeFileSync(pkg.path, `${JSON.stringify(pkg.data, null, "\t")}\n`);
72: }
73: 
74: if (totalUpdates === 0) {
75: 	console.log("\nAll inter-package dependencies are already in sync.");
76: } else {
77: 	console.log(`\nUpdated ${totalUpdates} dependency version(s).`);
78: }
